<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/Mail/ReceptionWorker.php';
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");$db=tnl_db();$identity=\TNL\Auth\SessionUser::require($db);if($identity['role']!=='admin'){http_response_code(403);exit('Solo administración.');}\TNL\Mail\Reception::init($db);$store=new \TNL\Mail\ExternalAccount($db,tnl_path('storage'));$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){tnl_check_csrf();try{if(($_POST['action']??'')==='activate'){$result=\TNL\Mail\Reception::activate($db,(string)($_POST['owner']??''),tnl_path('storage'));$notice='Recepción activada para '.$result['email'].'. Solo se procesarán mensajes nuevos.';}elseif(($_POST['action']??'')==='disable'){\TNL\Admin\Settings::set($db,'reception_enabled','0');$notice='Recepción automática desactivada.';}elseif(($_POST['action']??'')==='poll'){$result=\TNL\Mail\ReceptionWorker::poll($db,tnl_path('storage'),true);$notice=json_encode($result,JSON_UNESCAPED_UNICODE);}elseif(($_POST['action']??'')==='assign'){\TNL\Mail\Reception::assign($db,(int)$_POST['message_id'],(int)$_POST['user_id']);$notice='Conversación asignada.';}}catch(Throwable $e){$error=$e->getMessage();}}
$owner=\TNL\Mail\Reception::owner($db);$accounts=$db->query('SELECT owner,config FROM external_accounts')->fetchAll(PDO::FETCH_ASSOC);$sync=$db->query('SELECT * FROM reception_sync')->fetchAll(PDO::FETCH_ASSOC);$pending=$db->query('SELECT id,sender,subject,created_at FROM reception_messages WHERE assigned_user=0 ORDER BY id DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);$staff=\TNL\Mail\Reception::staff($db);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recepción compartida · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.12.4"><script src="assets/workspace.js?v=0.12.4" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar('admin','reception',$identity['name']);?><main class="main"><h1>Recepción compartida</h1><p>Una cuenta pública para el equipo. Las respuestas se asignan por conversación y marcador firmado; los clientes nuevos pueden responder con un nombre, cargo o dirección interna.</p><?php if($error):?><p class="error"><?=tnl_escape($error)?></p><?php endif;?><?php if($notice):?><p class="notice"><?=tnl_escape($notice)?></p><?php endif;?><section class="panel"><h2><?=$owner?'Recepción activa':'Selecciona el buzón público'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><label>Buzón<select name="owner"><?php foreach($accounts as $a):$cfg=json_decode($a['config'],true);?><option value="<?=tnl_escape($a['owner'])?>" <?=$owner===$a['owner']?'selected':''?>><?=tnl_escape($cfg['email'].' · '.$a['owner'])?></option><?php endforeach;?></select></label><p>Activar o reactivar toma el punto actual de IMAP y deja fuera los mensajes antiguos. Los usuarios con permiso de envío externo podrán elegir este buzón en «De». La respuesta automática incluye hasta 40 nombres, cargos y direcciones internas del directorio activo.</p><button name="action" value="activate">Activar desde ahora</button><button class="button-secondary" name="action" value="poll">Comprobar ahora</button><button class="button-ghost" name="action" value="disable">Desactivar</button></form><p>La revisión automática se ejecuta cada minuto mientras TNL Mail está abierto. Para recepción continua, programa cada minuto en el alojamiento: <code>php <?=tnl_escape(tnl_path('app/Mail/ReceptionWorker.php'))?></code>. El proceso respeta su intervalo de 1 minuto.</p><p>Las direcciones internas son identificadores de TNL Mail. Para recibir correo enviado directamente a ellas, el proveedor debe ofrecer alias o catch-all; el sistema no crea direcciones SMTP en el proveedor.</p><?php foreach($sync as $row):?><p><?=tnl_escape($row['mailbox'])?> · cursor <?=(int)$row['next_uid']?> · última revisión <?=tnl_escape($row['last_poll']?gmdate('c',(int)$row['last_poll']):'pendiente')?><?php if($row['last_error']):?> · <?=tnl_escape($row['last_error'])?><?php endif;?></p><?php endforeach;?></section><section class="panel" data-live-region="reception-queue"><h2>Mensajes que requieren revisión en el servidor</h2><?php foreach($db->query('SELECT uid,error,created_at FROM reception_errors ORDER BY created_at DESC LIMIT 20')->fetchAll(PDO::FETCH_ASSOC) as $failure):?><p>UID <?=(int)$failure['uid']?> · <?=tnl_escape($failure['error'].' · '.$failure['created_at'])?>. El original permanece en el buzón IMAP.</p><?php endforeach;?><h2>Pendientes de asignación</h2><?php if(!$pending):?><p>No hay mensajes pendientes.</p><?php endif;?><?php foreach($pending as $m):?><article><a href="reception-mail.php?id=<?=(int)$m['id']?>"><?=tnl_escape($m['subject'])?></a><p><?=tnl_escape($m['sender'].' · '.$m['created_at'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="message_id" value="<?=(int)$m['id']?>"><select name="user_id"><?php foreach($staff as $u):?><option value="<?=(int)$u['id']?>"><?=tnl_escape(\TNL\Mail\Directory::label($u))?></option><?php endforeach;?></select><button name="action" value="assign">Asignar conversación</button></form></article><?php endforeach;?></section></main></div></body></html>
